package com.jadhavr.erp.academic.repository; import com.jadhavr.erp.academic.entity.TimetableEntry; import com.jadhavr.erp.academic.enums.*; import org.springframework.data.jpa.repository.*; import java.time.LocalTime; import java.util.*; public interface TimetableEntryRepository extends JpaRepository<TimetableEntry,Long>,JpaSpecificationExecutor<TimetableEntry>{ @Query("select count(t)>0 from TimetableEntry t where t.status='ACTIVE' and t.dayOfWeek=:day and (t.section.id=:section or t.teacher.id=:teacher) and t.startTime<:end and t.endTime>:start") boolean hasClash(Long section,Long teacher,TimetableDay day,LocalTime start,LocalTime end); List<TimetableEntry> findBySectionIdAndStatusOrderByDayOfWeekAscStartTimeAsc(Long id,AcademicStatus s); }
